// /lib/backend-service.ts
import { TopicBuilderFormData } from '../types/topic-builder';

const BACKEND_API_URL = process.env.BACKEND_API_URL || 'http://127.0.0.1:2024';

export async function generateTopicsWithBackend(formData: TopicBuilderFormData) {
  try {
    const backendPayload = transformFormDataToBackendFormat(formData);

    const response = await fetch(`${BACKEND_API_URL}/api/topic/generate-topic`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(backendPayload),
    });

    if (!response.ok) {
      throw new Error(`Backend API error: ${response.status} ${response.statusText}`);
    }

    const result = await response.json();
    return {
      topics: result.topics,
      request_id: result.request_id,
      model_used: result.model_used,
      generation_time_ms: result.generation_time_ms,
    };
  } catch (error) {
    console.error('Backend API error:', error);
    throw error;
  }
}

function transformFormDataToBackendFormat(formData: TopicBuilderFormData) {
  const { wizardMode, industry, subject, content_type, audience, purpose, tone } = formData;

  return {
    industry: industry,
    subject: subject,
    content_type: content_type,
    platform: formData.platform,
    audience: audience,
    purpose: purpose,
    tone: tone,
    keywords: formData.keywords,
    exclude: formData.exclude,
    num_ideas: formData.num_ideas,
    industry_specific_focus: formData.focus,
    additional_notes: formData.notes,
    content_timing_preference: formData.fresh_vs_evergreen,
    content_originality_preference: formData.safe_vs_original,
    demographic_location: Array.isArray(formData.demographic_location) ? 
      formData.demographic_location : 
      [formData.demographic_location],
    timestamp: new Date().toISOString(),
    wizard_mode: wizardMode
  };
}

// /app/api/generate-topics/route.ts
import { NextResponse } from 'next/server';
import { generateTopicsWithBackend } from '@/lib/backend-service';
import { TopicBuilderFormData } from '@/types/topic-builder';

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const formData = body.formData as TopicBuilderFormData;

    // Validate the request data
    if (!formData || !formData.industry) {
      return NextResponse.json(
        { error: 'Invalid request data' },
        { status: 400 }
      );
    }

    const result = await generateTopicsWithBackend(formData);

    return NextResponse.json({
      topics: result.topics,
      request_id: result.request_id,
      generated_at: new Date().toISOString(),
      model_used: result.model_used,
      generation_time_ms: result.generation_time_ms
    });
  } catch (error) {
    console.error('Topic generation error:', error);
    return NextResponse.json(
      { 
        error: 'Failed to generate topics',
        error_code: 'generation_failed',
        fallback_available: false
      },
      { status: 500 }
    );
  }
}
```

