// /components/topic-builder/WizardNavigation.tsx with keyboard support
import { useEffect, useRef } from 'react';

interface WizardNavigationProps {
  currentStep: number;
  totalSteps: number;
  canGoNext: boolean;
  canGoPrev: boolean;
  onNext: () => void;
  onPrev: () => void;
}

export function WizardNavigation({ 
  currentStep, 
  totalSteps, 
  canGoNext, 
  canGoPrev, 
  onNext, 
  onPrev 
}: WizardNavigationProps) {
  const nextButtonRef = useRef<HTMLButtonElement>(null);

  // Add keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Allow keyboard navigation only when not in an input field
      const activeElement = document.activeElement;
      const isInputActive = activeElement instanceof HTMLInputElement || 
                           activeElement instanceof HTMLTextAreaElement || 
                           activeElement instanceof HTMLSelectElement;

      if (isInputActive) return;

      if (e.key === 'ArrowRight' && canGoNext) {
        onNext();
      } else if (e.key === 'ArrowLeft' && canGoPrev) {
        onPrev();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [canGoNext, canGoPrev, onNext, onPrev]);

  // Focus next button when step changes
  useEffect(() => {
    if (nextButtonRef.current) {
      nextButtonRef.current.focus();
    }
  }, [currentStep]);

  return (
    <div className="wizard-navigation" role="navigation" aria-label="Wizard Navigation">
      <div className="step-indicator" aria-hidden="true">
        {Array.from({ length: totalSteps }).map((_, index) => (
          <div 
            key={index} 
            className={`step-dot ${index + 1 === currentStep ? 'active' : ''} ${index + 1 < currentStep ? 'completed' : ''}`}
          />
        ))}
      </div>

      <div className="step-counter" aria-live="polite">
        Step {currentStep} of {totalSteps}
      </div>

      <div className="navigation-buttons">
        <button
          onClick={onPrev}
          disabled={!canGoPrev}
          className="prev-button"
          aria-label="Previous Step"
        >
          Back
        </button>

        <button
          ref={nextButtonRef}
          onClick={onNext}
          disabled={!canGoNext}
          className="next-button"
          aria-label={currentStep === totalSteps ? 'Generate Topics' : 'Next Step'}
        >
          {currentStep === totalSteps ? 'Generate Topics' : 'Next'}
        </button>
      </div>
    </div>
  );
}

