}

// /hooks/use-media-query.ts
import { useState, useEffect } from 'react';

export function useMediaQuery(query: string): boolean {
  // Default to false for SSR
  const [matches, setMatches] = useState(false);

  useEffect(() => {
    // Create media query list
    const mediaQuery = window.matchMedia(query);

    // Set initial value
    setMatches(mediaQuery.matches);

    // Create event listener
    const handler = (event: MediaQueryListEvent) => setMatches(event.matches);

    // Add event listener
    mediaQuery.addEventListener('change', handler);

    // Clean up
    return () => mediaQuery.removeEventListener('change', handler);
  }, [query]);

  return matches;
}

// Example of responsive component
import { useResponsiveLayout } from '@/hooks/use-responsive-layout';

export function ResponsiveTopicList({ topics }) {
  const { isMobile, isTablet } = useResponsiveLayout();

  if (isMobile) {
    return (
      <div className="mobile-topic-list">
        {/* Simplified mobile layout */}
        {topics.map(topic => (
          <MobileTopicCard key={topic.id} topic={topic} />
        ))}
      </div>
    );
  }

  if (isTablet) {
    return (
      <div className="tablet-topic-grid">
        {/* 2-column grid for tablets */}
        {topics.map(topic => (
          <TopicCard key={topic.id} topic={topic} />
        ))}
      </div>
    );
  }

  return (
    <div className="desktop-topic-grid">
      {/* 3-column grid for desktop */}
      {topics.map(topic => (
        <TopicCard key={topic.id} topic={topic} />
      ))}
    </div>
  );
}
